import{_ as e,o as d,c as o,a2 as i}from"./chunks/framework.BM5YPQmL.js";const l=JSON.parse('{"title":"TUI 服务表面","description":"","frontmatter":{},"headers":[],"relativePath":"zh/l1/tui-ext.md","filePath":"zh/l1/tui-ext.md"}'),r={name:"zh/l1/tui-ext.md"};function c(a,t,s,u,n,_){return d(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="tui-服务表面" tabindex="-1">TUI 服务表面 <a class="header-anchor" href="#tui-服务表面" aria-label="Permalink to &quot;TUI 服务表面&quot;">​</a></h1><p>桌面住在 TUI 服务（<code>ocos/services/tui/</code>）里，并经 L1SVC &quot;tui&quot; 类别触达 ring 3（操作族 1-9：<code>tui</code>、<code>tui-test</code>、<code>tui-hw</code>、 <code>tui-net</code>、<code>tui-sysinfo</code>、<code>tui-time</code>、<code>tui-drv</code>、<code>tui-sys</code>、 <code>tui-ext</code>）。</p><h2 id="扩展注册表-svc-tui-api-h" tabindex="-1">扩展注册表（svc_tui_api.h） <a class="header-anchor" href="#扩展注册表-svc-tui-api-h" aria-label="Permalink to &quot;扩展注册表（svc_tui_api.h）&quot;">​</a></h2><p>所有表都是静态的（独立环境编译、无 malloc 依赖）；注册成功 返回 0，表满返回 -1，名字/键重复返回 -2。每个条目携带其所有者 （树内页为 &quot;builtin-...&quot;），因此注销可用且重复注册是幂等的。</p><table tabindex="0"><thead><tr><th>注册表</th><th>API</th><th>新增什么</th></tr></thead><tbody><tr><td>menu</td><td><code>tui_menu_register/unregister/list/sort</code></td><td>一个启动器项：label、desc、ASCII 图标、group、hotkey、priority、动作回调</td></tr><tr><td>page</td><td><code>tui_page_register/unregister/list/render/input</code></td><td>一个完整页面：render(win, scroll) + input(key) -&gt; 1 已消费；<code>tui_ext_page_main</code> 是通用 runner</td></tr><tr><td>widget</td><td><code>tui_widget_register/unregister/list/render/event</code></td><td>一种可复用部件类型</td></tr><tr><td>command</td><td><code>tui_cmd_register/unregister/list/execute</code></td><td>一个 TUI 命令行钩子</td></tr><tr><td>theme</td><td><code>tui_theme_register/unregister/list/set</code></td><td>颜色主题</td></tr><tr><td>hotkey</td><td><code>tui_key_register/unregister/list/conflict</code></td><td>全局热键（内置冲突检测）</td></tr><tr><td>event</td><td><code>tui_event_register/unregister/list/dispatch</code></td><td>通用事件订阅者</td></tr></tbody></table><p>限额是命名常量（<code>TUI_EXT_MENU_MAX</code>、...）- 有界表、响亮地 拒绝、绝不截断。</p><h2 id="参考实现" tabindex="-1">参考实现 <a class="header-anchor" href="#参考实现" aria-label="Permalink to &quot;参考实现&quot;">​</a></h2><p>树内页面正是这样注册的 - <code>svc_tui_time.c</code>（<code>time.clock</code>、 <code>time.tz</code>、<code>time.set</code>）、<code>svc_tui_sys.c</code>（<code>sys.host</code>、...）、 hw/net/sysinfo/drv/sys 各族，以及桌面应用（<code>svc_tui_dt_*.c</code>）。 写你自己的之前先读一个：init 时注册、teardown 时注销、带所有者 标签。</p><h2 id="页面与程序" tabindex="-1">页面与程序 <a class="header-anchor" href="#页面与程序" aria-label="Permalink to &quot;页面与程序&quot;">​</a></h2><p>TUI 渲染的是合并应用包装的同一批服务 - sysinfo 页读的正是 <code>hwinfo</code> 读的那些 L1SVC 操作。TUI 页是内核内的服务表面（经上面 的注册表）；大应用是 ring-3 程序；两扇门通向同一状态。</p>',10)])])}const p=e(r,[["render",c]]);export{l as __pageData,p as default};
